// Reuse verified generated bytes, never link a target to retained source files.
import {mkdir,readdir,link,writeFile,realpath} from 'node:fs/promises';
import {resolve,join,dirname,relative,isAbsolute,sep} from 'node:path';
import {createHash} from 'node:crypto';
import {readLayerManifest,verifyLayerManifests,verifyLayerWorkspace} from '../../../.platform-reconstitution/sourcery-core/src/kernel/composition.mjs';
export {readLayerManifest};

export async function composeLayerWorkspaces({platform,capabilities,applications,target}){
 const reuse=resolve(process.env.SOURCERY_RECONCILIATION_REUSE_TARGET||'');
 const workspace=resolve(import.meta.dirname,'../../..');
 const expected=join(workspace,'.platform-reconstitution/reconciled-validation-2026-11-04-r2/assembled');
 if(reuse.toLowerCase()!==expected.toLowerCase())throw new Error('Reuse must name the prior generated assembly, never a source checkout.');
 const destination=resolve(target),allowed=join(workspace,'.platform-reconstitution');
 if(!destination.startsWith(allowed+sep)||destination===reuse)throw new Error('Unexpected linked validation target.');
 const existing=await readdir(destination).catch(error=>error.code==='ENOENT'?[]:Promise.reject(error));
 if(existing.length)throw new Error('Linked validation target must be empty.');
 const manifests=await Promise.all([platform,capabilities,applications].map(readLayerManifest));
 const graph=verifyLayerManifests(manifests),roots=[resolve(platform),reuse,reuse],verifications=[];
 await mkdir(destination,{recursive:true});
 for(const [index,manifest] of manifests.entries()){
  verifications.push({...await verifyLayerWorkspace(roots[index],manifest),verificationRoot:roots[index]});
  const base=await realpath(roots[index]);
  for(const file of manifest.files){
   const source=await realpath(join(base,...file.path.split('/'))),fromBase=relative(base,source);
   if(!fromBase||fromBase==='..'||fromBase.startsWith('..'+sep)||isAbsolute(fromBase))throw new Error('Generated materialization input escaped its verified root.');
   const output=join(destination,...file.path.split('/'));await mkdir(dirname(output),{recursive:true});await link(source,output);
  }
 }
 const receipt={protocol:'sourcery/local-linked-layer-composition-proof.v1',referenceHash:graph.referenceHash,fileCount:graph.fileCount,layerDigests:manifests.map(({repository,layerDigest})=>({repository,layerDigest})),projectionAuthority:false,materialization:'hardlinks between generated workspaces; no retained source files linked',readOnlyValidation:true};
 receipt.proofHash=createHash('sha256').update(JSON.stringify(receipt)).digest('hex');
 await writeFile(join(destination,'.sourcery-composition.json'),JSON.stringify(receipt,null,2)+'\n');
 await writeFile(join(destination,'.LINKED-VALIDATION-READ-ONLY.txt'),'Generated validation only. Editing these linked files also changes the associated generated snapshot or prior generated assembly. Retained source repositories are not linked.\n');
 return{...receipt,verifications};
}
